   "tid": "p12arex129",
   "q": "الشاعر: (علي محمود طه المهندس)، ينتمي الى جماعة (أبولو)، مدّي لعينيه الرحاب الفساح، ورقرقي الاضواء في جفنهِ، وأمسكي يا أرض عصف الرياح، والراعد المنصبَّ في أذنهِ، طغىٰ الأسى الداوي علىٰ صوتهِ، ياللصدى من قلبه الناطق، مضى يبثُ الدهرَ في خفته، شكاية الخلق الىٰ الخالق، أنتِ له يا أرضُ أمُّ رؤوم، فاشهدي الكون على شقوته، وردّدي شكواه بين النجوم، فهو ابنك الانسان في حيرته",
