   "why": "الموضوع الأول: قال رسول الله (صلى الله عليه وآله وصحبه وسلم): (سلوا الله علماً نافعاً، وتعوّذوا بالله من علم لا ينفع). هذا الحديث الشريف يعلمنا أن العلم النافع هو ما يقربنا من الله ويفيدنا في ديننا ودنيانا، والعلم الذي لا ينفع هو ما لا فائدة منه ولا يقربنا من الله. فعلينا أن نسأل الله العلم النافع وأن نتعوذ به من العلم الذي لا ينفع. الموضوع الثاني: قال الشاعر: كم من أخ لو نابتك نائبة، وجدته لك خيراً من أخ النسب. الصديق الوفي لا يوزن بميزان ولا يُقدّر بثمن. فالصديق الوفي هو من يقف معك في الشدة والرخاء، وهو من ينصحك إذا أخطأت ويفرح إذا أصبت. والصديق الوفي كنز لا يقدر بثمن.",
