   "c": -1,
   "why": "لم تترك جماعة الديوان أتباعاً ولم تُخلِق مدرسة شعرية؛ لأنّ شعرهم لا تنطبق عليه ملامح المدرسة من الاتّباع والشيوع؛ إذ اجتمعوا تجمّعاً أدبياً حول مجلة لا مدرسةً قائمةً على منهجٍ مُستقلّ، وليس من المعقول أن نصف شعر شخصين أو ثلاثة بالمدرسة، مع آرائهم النقدية السديدة ورغبتهم في التجديد ودعوتهم إليه. ثمّ إنّهم أخفقوا في تطبيق آرائهم النقدية على شعرهم كما أخفقوا في إحاطة شعر غيرهم بها، فلم يبقَ منهجٌ يُحتذى ولا أتباعٌ يُقلَّدون.",
