   "why": "الحكم: هو الاستثناء المُفرَغ (المنقطع)، لأن المستثنى «ما اضطررتم إليه» ليس من جنس المستثنى منه، إذ إن المذكور «مما أكلتم» مذكور مطلق يشمل كل طعام، والمُستثنى منه ضرورةٌ وحدها، فلم يشاركه في الجنس. وإعراب المستثنى: «ما» حرف مبني على السكون لا محلّ له من الإعراب، و«اضطررتم» فعل ماضٍ مبني على السكون لاتصاله بواو الجماعة، والواو ضمير متصل مبني على الفتح في محل رفع فاعل، و«إليه» جار ومجرور متعلّقان بالفعل «اضطررتم»، والمجموع «ما اضطررتم إليه» في محل نصب مستثنى متأخّر. وحكمه النصب لعدم اتصاله بما قبله.",
