   "q": "ب) أولا : ما نوع ( ما ) في البيتين الأتيين ؟ ١) قال المتنبي : وما ماضي الشباب بمستردً ولا يوم يمرُّ بمُستعاد ٢) قال أبو ذؤيب الهذلي : ما بال عيني لا تجفُ دُموعُها كثيرٌ تشكَيها قليلٌ مُجوعُها . ثانياً : قال عمر بن أبي ربيعة : لقد دبَّ الهوى لكِ في فُؤادي دَبيبَ دَمِ الحياةِ إلى العُروقِ . استفهم عما تحته خط بحرف استفهام مرة ، وباسم استفهام مرة أخرى",
