   "q": "ج) ١) قال جميل بثينة : فهل لي في كتمان حبِّي راحة وهل تنفعنّي بوحهٌ لو أبوحُها . ما نوع النفي الوارد في البيت ؟ وما أسلوبه ؟ ثمّ أظهر النغي في الشطر الثاني باداة تنفي الفعل بزمن الماضي المتصل بالحاضر . ٢) قال الشاعر إبراهيم ناجي : ليت شعري اين منه مهربي أين يمضي هارب من دمه . ما إعراب ( اين ) الواردة مرتين مع ذكر السبب ؟",
