   "c": -1,
   "why": "أولًا (جميل بثينة): «فهل لي في كتمان حبّي راحة» — نوع النفي: النفي والسلب بـ«ليس» أو «لا»... والصواب: البيت لا يحوي نفيًا صريحًا، وإنما هو استفهام «هل» يفيد التمنّي، وأسلوبه: أسلوب الاستفهام المتمنّي، والمعنى: ليتني أبدي حبّي. أمّا «هل تنفعنّي بوحه لو أبوحُها» فأسلوب شرط ممزوج بالقسم. والمراد إظهار النفي في الشطر الثاني بأداة تنفي الفعل المضارع بزمن الماضي المتصل بالحاضر: نضع «لم» + مضارع، فيصير: «فما نفعتني بوحُهُ لو أباحتْه». ثانيًا (إبراهيم ناجي) «أينَ مناهري»: «أين» اسم استفهام مبني على الفتح في محل رفع مبتدأ، ومعناها الاستفهام عن المكان يخرج إلى التحسّر، والتقدير: «ليتني أجد مناهري»؛ و«أين» الثانية متعلّقة بمحذوف خبر، والجملة اسمية في محل نصب حال.",
