   "q": "أ) للشاعر (عبد المحسن الكاظمي) قصيدة في منهجك، ما عنوانها؟ ولم كانت؟ اكتب له ثلاثة أبيات تجد فيها الصحة اللغوية مضبوطة بالشكل",
   "o": [],
   "c": -1,
   "why": "الشاعر هو عبد المحسن الكاظمي (1870–1917م)، شاعر عراقي رائد، من روّاد النهضة الشعرية في العراق، وُلد في الكاظمية وتوفّى فيها. وقد نظم قصيدةً في المنهج تُ dealing بالوطن والطبيعة والشوق. ومن أشهر قصائده: «يا حبيبتاه»، و«أنا الطالب»، و«الشوق إلى الوطن»، وقد امتاز لغته بالبساطة والجزالة وقوة المعنى. (تنبيه: يطلب السؤال كتابة ثلاثة أبياتٍ من قصيدته مضبوطةً بالشكل وجدًا فيها الصحة اللغوية، فيلتزم الطالب بأبيات الكتاب المدرسي كما وردت فيه مضبوطةً، ولا يُجزَل فيها النقل عن ظاهر الكتاب.)",
