   "q": "(ج) من جاء بعد القاص (محمود تيمور) في حقبة ما بين الحربين؟ وعم تحدثا في قصصهما؟",
   "o": [],
   "c": -1,
   "why": "جاء بعد القاص محمود تيمور في حقبة ما بين الحربين عددٌ من القاصّين، منهم: إبراهيم الكيلاني، ومحمود السعدني، ومحمد العيدروس. وقد تحدّث الكيلاني في قصصه عن الواقع الاجتماعي والقروي، وصوّر حياة الفلاحين وصراعاتهم وآمالهم، بينما تحدّث السعدني في قصصه عن أوضاع الأطفال في المدينة وظروفهم المعيشية والنفسية، فكان قاصًّا قريبًا من الطفل محبًّا له. ويُضاف إلى ذلك أنّ القاصّين بعده تأثّروا بتجربة محمود تيمور فوسّعوا المجال القصصي واجتهدوا في التجديد.",
