   "c": -1,
   "why": "يُعدّ عبد الرحمن شكري بالنسبة لزميليه العقاد والمازني: هو المثقّف الناقد والمترجم، وهو أصغرهم سنًّا وأقلّهم إصدارًا، وقد ترجم أعمال الفيلسوف الألماني نيتشه إلى العربية وأثّر بها في نظرته الفلسفية. وقد وصفه العقاد بأنه «صديقٌ صامت» محبٌّ للتأمّل وال pensée، وقد كتب في الأدب والنقد والفلسفة، واشتُهر بدرايته الواسعة ونضجه الفكري، مع قلّة إنتاجه الشعري، فكان العنصر الفكري في الثلاثة.",
