   "q": "(ب): علل اثنتين مما يأتي: ١) لم يطلق لفظ مدرسة على جماعة الديوان. ٢) قصيدة السياب (هل كان حباً) وقصيدة نازك الملائكة (الكوليرا)، لم تمثلا الشعر الحر بكل سماته. ٣) يُعد (أحمد شوقي) رائداً للشعر المسرحي",
